#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6
ENV_FILE=".env.azure"
REPO_ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
cd "$REPO_ROOT"

banner "Baileys scheduler on Azure"

# ── Example stage: replace with your real steps ───────────────────────────
stage "Azure account"
if ! command -v az >/dev/null 2>&1; then
  warn "Azure CLI is required: https://learn.microsoft.com/cli/azure/install-azure-cli"
  exit 1
fi
if command -v node >/dev/null 2>&1; then
  NODE_COMMAND=node
elif command -v node.exe >/dev/null 2>&1; then
  NODE_COMMAND=node.exe
else
  warn "Node.js 20 or newer is required."
  exit 1
fi
if ! az account show >/dev/null 2>&1; then
  say "Azure CLI is not signed in. Your browser will open for login."
  az login >/dev/null
fi
AZURE_SUBSCRIPTION_ID=$(az account show --query id --output tsv | tr -d '\r')
AZURE_SUBSCRIPTION_NAME=$(az account show --query name --output tsv | tr -d '\r')
say "Using subscription: $AZURE_SUBSCRIPTION_NAME ($AZURE_SUBSCRIPTION_ID)"
if ! confirm "Use this Azure subscription?"; then
  step "Run 'az account set --subscription <id>' and restart this wizard."
  exit 1
fi
write_env AZURE_SUBSCRIPTION_ID "$AZURE_SUBSCRIPTION_ID"

stage "Names and region"
ask AZURE_LOCATION "Azure region [centralindia]:"
AZURE_LOCATION=${AZURE_LOCATION:-centralindia}
suffix=$(date +%s)
ask AZURE_RESOURCE_GROUP "Resource group [baileys-scheduler-rg]:"
AZURE_RESOURCE_GROUP=${AZURE_RESOURCE_GROUP:-baileys-scheduler-rg}
ask AZURE_APP_NAME "Globally unique app name [baileys-scheduler-$suffix]:"
AZURE_APP_NAME=${AZURE_APP_NAME:-baileys-scheduler-$suffix}
AZURE_PLAN_NAME="${AZURE_APP_NAME}-plan"
if [[ ! "$AZURE_LOCATION" =~ ^[a-z0-9]+$ || ! "$AZURE_RESOURCE_GROUP" =~ ^[a-zA-Z0-9._()-]+$ || ! "$AZURE_APP_NAME" =~ ^[a-z0-9-]+$ ]]; then
  warn "The region, resource group, or app name contains unsupported characters."
  exit 1
fi
write_env AZURE_LOCATION "$AZURE_LOCATION"
write_env AZURE_RESOURCE_GROUP "$AZURE_RESOURCE_GROUP"
write_env AZURE_APP_NAME "$AZURE_APP_NAME"
write_env AZURE_PLAN_NAME "$AZURE_PLAN_NAME"

stage "Admin token"
say "Every pairing and scheduling request requires this bearer token."
ask_secret SCHEDULER_TOKEN "Admin token [Enter generates one]:"
if [[ -z "$SCHEDULER_TOKEN" ]]; then
  if command -v openssl >/dev/null 2>&1; then
    SCHEDULER_TOKEN=$(openssl rand -hex 32)
  else
    SCHEDULER_TOKEN=$("$NODE_COMMAND" -e "process.stdout.write(require('crypto').randomBytes(32).toString('hex'))")
  fi
fi
if (( ${#SCHEDULER_TOKEN} < 32 )); then
  warn "The admin token must contain at least 32 characters."
  exit 1
fi
write_env SCHEDULER_TOKEN "$SCHEDULER_TOKEN"

stage "Create and deploy"
say "This creates one Linux App Service B1 plan, currently about USD 13/month before tax."
warn "The plan is billable until you delete resource group '$AZURE_RESOURCE_GROUP'."
if ! confirm "Create the Azure resources and deploy now?"; then
  say "Nothing billable was created. Re-run when ready."
  exit 0
fi
az account set --subscription "$AZURE_SUBSCRIPTION_ID"
az group create --name "$AZURE_RESOURCE_GROUP" --location "$AZURE_LOCATION" --output none
az appservice plan create \
  --name "$AZURE_PLAN_NAME" \
  --resource-group "$AZURE_RESOURCE_GROUP" \
  --location "$AZURE_LOCATION" \
  --sku B1 \
  --is-linux \
  --output none
az webapp create \
  --name "$AZURE_APP_NAME" \
  --resource-group "$AZURE_RESOURCE_GROUP" \
  --plan "$AZURE_PLAN_NAME" \
  --runtime "NODE|24-lts" \
  --output none
az webapp config appsettings set \
  --name "$AZURE_APP_NAME" \
  --resource-group "$AZURE_RESOURCE_GROUP" \
  --settings \
    SCHEDULER_TOKEN="$SCHEDULER_TOKEN" \
    DATA_DIR=/home/data/baileys-scheduler \
    LOG_LEVEL=warn \
    SCM_DO_BUILD_DURING_DEPLOYMENT=true \
  --output none
az webapp config set \
  --name "$AZURE_APP_NAME" \
  --resource-group "$AZURE_RESOURCE_GROUP" \
  --always-on true \
  --http20-enabled true \
  --min-tls-version 1.2 \
  --startup-file "npm run scheduler" \
  --output none
az webapp update \
  --name "$AZURE_APP_NAME" \
  --resource-group "$AZURE_RESOURCE_GROUP" \
  --https-only true \
  --output none
az webapp log config \
  --name "$AZURE_APP_NAME" \
  --resource-group "$AZURE_RESOURCE_GROUP" \
  --application-logging filesystem \
  --level warning \
  --web-server-logging off \
  --output none
DEPLOY_DIR=$(mktemp -d "$REPO_ROOT/.azure-deploy.XXXXXX")
DEPLOY_ZIP="${DEPLOY_DIR}.zip"
trap 'rm -rf "$DEPLOY_DIR"; rm -f "$DEPLOY_ZIP"' EXIT
mkdir -p "$DEPLOY_DIR/Example"
cp package.json yarn.lock .yarnrc.yml engine-requirements.js tsconfig.json tsconfig.build.json "$DEPLOY_DIR"
cp Example/scheduler.ts Example/scheduler-store.ts Example/scheduler.html "$DEPLOY_DIR/Example"
cp -R src WAProto "$DEPLOY_DIR"
(
  cd "$DEPLOY_DIR"
  npx --yes corepack@0.34.0 yarn set version 4.9.2 --yarn-path
)
git -C "$DEPLOY_DIR" init --quiet
git -C "$DEPLOY_DIR" add .
DEPLOY_TREE=$(git -C "$DEPLOY_DIR" write-tree)
git -C "$DEPLOY_DIR" archive --format=zip --output="$DEPLOY_ZIP" "$DEPLOY_TREE"
AZURE_DEPLOY_ZIP="$DEPLOY_ZIP"
if [[ "$(command -v az)" == /mnt/* ]] && command -v wslpath >/dev/null 2>&1; then
  AZURE_DEPLOY_ZIP=$(wslpath -w "$DEPLOY_ZIP")
elif command -v cygpath >/dev/null 2>&1; then
  AZURE_DEPLOY_ZIP=$(cygpath -w "$DEPLOY_ZIP")
fi
az webapp deploy \
  --name "$AZURE_APP_NAME" \
  --resource-group "$AZURE_RESOURCE_GROUP" \
  --src-path "$AZURE_DEPLOY_ZIP" \
  --type zip \
  --clean true \
  --restart true \
  --output none
rm -rf "$DEPLOY_DIR"
rm -f "$DEPLOY_ZIP"
trap - EXIT
APP_URL="https://${AZURE_APP_NAME}.azurewebsites.net"
write_env APP_URL "$APP_URL"

stage "Pair WhatsApp"
say "Wait for the app to report healthy, then link it as a companion device."
for _ in {1..30}; do
  if curl --fail --silent "$APP_URL/health" >/dev/null; then break; fi
  sleep 10
done
if ! curl --fail --silent "$APP_URL/health"; then
  warn "The app did not become healthy. Inspect logs with:"
  step "az webapp log tail -g $AZURE_RESOURCE_GROUP -n $AZURE_APP_NAME"
  exit 1
fi
printf '\n'
ask_secret WHATSAPP_PHONE "WhatsApp phone, digits with country code:"
if [[ "$(curl --fail --silent "$APP_URL/health")" == *'"connected":true'* ]]; then
  say "WhatsApp is already connected; pairing is not needed."
else
  PAIR_RESPONSE=$(curl --fail --silent --show-error \
    --request POST \
    --header "Authorization: Bearer $SCHEDULER_TOKEN" \
    --header "Content-Type: application/json" \
    --data "{\"phone\":\"$WHATSAPP_PHONE\"}" \
    "$APP_URL/pair")
  say "Pairing response: $PAIR_RESPONSE"
  step "WhatsApp mobile app > Linked devices > Link a device > Link with phone number."
  step "Enter the code shown above."
  pause "Press Enter after WhatsApp confirms the link."
fi

stage "Smoke test"
HEALTH=$(curl --fail --silent "$APP_URL/health")
say "Health: $HEALTH"
say "The test schedules a message to the same phone two minutes from now."
ask TEST_TEXT "Test message [Baileys scheduler test]:"
TEST_TEXT=${TEST_TEXT:-Baileys scheduler test}
TEST_SEND_AT=$("$NODE_COMMAND" -e "process.stdout.write(new Date(Date.now()+120000).toISOString())")
if confirm "Schedule the test message?"; then
  TEST_BODY=$("$NODE_COMMAND" -e "process.stdout.write(JSON.stringify({phone:process.argv[1],text:process.argv[2],sendAt:process.argv[3]}))" "$WHATSAPP_PHONE" "$TEST_TEXT" "$TEST_SEND_AT")
  curl --fail --silent --show-error \
    --request POST \
    --header "Authorization: Bearer $SCHEDULER_TOKEN" \
    --header "Content-Type: application/json" \
    --data "$TEST_BODY" \
    "$APP_URL/messages"
  printf '\n'
fi
say "API URL: $APP_URL"
say "Configuration: $ENV_FILE (keep it private)"
# ──────────────────────────────────────────────────────────────────────────

finish
